import React from 'react';
import { CCopy, Descriptions, IconApps, Link, Message } from '@cloud-materials/common';

export default () => (
  <Descriptions
    column={1}
    data={[
      {
        label: '自定义复制触发Icon',
        value: <CCopy triggerIcon={<IconApps />} />,
      },
      {
        label: '自定义复制触发元素(优先级更高)',
        value: <CCopy triggerEle={<Link>复制</Link>} triggerIcon={<IconApps />} />,
      },
      {
        label: '自定义弹出框配置',
        value: <CCopy text="hi, it's copy" tooltip="点击这里就能复制哦" arcoPopoverProps={{ position: 'lt' }} />,
      },
      {
        label: '自定义复制完成消息',
        value: <CCopy text="hi, it's copy" successMessage="恭喜，复制完成" failMessage="糟糕，出错了" />,
      },
      {
        label: '自定义复制完成回调',
        value: (
          <CCopy
            text="hi, it's copy"
            onCopy={(text, result) => Message.info(`${text} - ${result ? '复制成功' : '复制失败'}`)}
          />
        ),
      },
      {
        label: '自定义复制完成回调&禁用默认popover提示',
        value: (
          <CCopy
            text="hi, it's copy"
            onCopy={(text, result) => Message.info(`${text} - ${result ? '复制成功' : '复制失败'}`)}
            arcoPopoverProps={{ popupVisible: false }}
          />
        ),
      },
    ]}
  />
);

import React from 'react';
import { useCCopy, Message } from '@cloud-materials/common';

export default () => {
  const [, controls] = useCCopy({
    text: '我是想放在文本上点击复制的内容',
    onCopy: (_, Result) => (Result ? Message.success('操作成功') : Message.error('操作失败')),
  });
  return (
    <p onClick={controls.handleCopy} style={{ cursor: 'pointer' }}>
      Hi, Headless UI 点击复制
    </p>
  );
};
